#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
SRC_UI="$ROOT/cs16-panel/public/index.php"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
RUNTIME="/etc/hyper-cs16/runtime.json"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-sql-external-v1-${STAMP}"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing $SRC_CTL"; exit 2; }
[[ -f "$SRC_UI" ]] || { echo "[ERROR] missing $SRC_UI"; exit 2; }

DOMAIN="www.avito.hyper-host.pw"
if [[ -f "$RUNTIME" ]]; then
  D="$(python3 - "$RUNTIME" <<'PY' 2>/dev/null || true
import json,sys
try:
    d=json.load(open(sys.argv[1],encoding='utf-8'))
    print(str(d.get('domain') or ''))
except Exception:
    pass
PY
)"
  [[ -n "$D" ]] && DOMAIN="$D"
fi
LIVE_UI="/var/www/hyper-host-sites/${DOMAIN}/public_html/index.php"

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
cp -a "$SRC_UI" "$BACKUP/index.repo.php"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$LIVE_UI" ]] && cp -a "$LIVE_UI" "$BACKUP/index.live.php"
[[ -f /etc/mysql/mariadb.conf.d/99-hyper-cs16-external.cnf ]] && cp -a /etc/mysql/mariadb.conf.d/99-hyper-cs16-external.cnf "$BACKUP/" || true

PATCHER="$(mktemp)"
echo '' | base64 -d > "$PATCHER"

echo "=============================================================="
echo " HYPER-HOST SQL EXTERNAL ACCESS v1"
echo " Server: #$SID"
echo " Public: 90.189.208.25:3306"
echo " LAN:    192.168.0.179:3306"
echo " Backup: $BACKUP"
echo "=============================================================="

echo "[1/6] Patch controller + SQL page..."
python3 "$PATCHER" "$SRC_CTL" "$SRC_UI"

echo "[2/6] Syntax validation..."
python3 -m py_compile "$SRC_CTL"
php -l "$SRC_UI" >/dev/null

echo "[3/6] Install live files..."
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
if [[ -f "$LIVE_UI" ]]; then
  install -m 0644 "$SRC_UI" "$LIVE_UI"
else
  echo "[WARN] live UI not found: $LIVE_UI"
fi
python3 -m py_compile "$LIVE_CTL"
[[ -f "$LIVE_UI" ]] && php -l "$LIVE_UI" >/dev/null

echo "[4/6] Enable/recover external SQL for server #$SID..."
"$LIVE_CTL" sql-external-enable "$SID"

echo "[5/6] Reload PHP..."
for svc in php8.3-fpm php8.2-fpm php8.1-fpm php8.0-fpm php-fpm; do
  if systemctl list-unit-files "$svc.service" >/dev/null 2>&1; then
    systemctl reload "$svc.service" 2>/dev/null || systemctl restart "$svc.service" 2>/dev/null || true
  fi
done

echo "[6/6] Verification..."
echo "--- sql-status ---"
"$LIVE_CTL" sql-status "$SID" || true
echo
echo "--- MariaDB TCP listener ---"
ss -ltnp | grep ':3306' || true
echo
echo "--- local login test through game credentials ---"
python3 - "$SID" <<'PY'
import json,sys
from pathlib import Path
sid=int(sys.argv[1])
p=Path(f'/var/lib/hyper-cs16/servers/{sid}.json')
d=json.load(open(p,encoding='utf-8'))
try:
    import pymysql
    con=pymysql.connect(host='127.0.0.1',port=3306,user=d['sql_user'],password=d['sql_password'],database=d['sql_db'],connect_timeout=5)
    with con.cursor() as cur:
        cur.execute('SELECT DATABASE(),CURRENT_USER()')
        print(cur.fetchone())
    con.close()
except Exception as exc:
    print('LOGIN TEST ERROR:',exc)
PY

rm -f "$PATCHER"

echo
echo "=============================================================="
echo " [SUCCESS] SQL EXTERNAL ACCESS v1 INSTALLED"
echo "=============================================================="
echo "Panel:"
echo "  http://www.avito.hyper-host.pw/?page=sql&server_id=$SID"
echo
echo "Choose:"
echo "  Internet: 90.189.208.25:3306"
echo "  LAN:      192.168.0.179:3306"
echo
echo "AMXX remains on 127.0.0.1:3306."
echo "Only the dedicated per-server SQL user is granted externally."
echo "Backup: $BACKUP"
